int [main](https://docs.opencv.org/4.x/dc/d89/highgui__qt_8cpp.html#a0ddf1224851353fc92bfbff6f499fa97)(int argc, char** argv)
{
// read image and error pattern
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) original_, mask_;
original_ = imread("images/kodim22.png");
mask_ = imread("images/pattern_random.png", IMREAD_GRAYSCALE);
// make sure that mask and source image have the same size
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) mask;
resize(mask_, mask, original_.[size](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a146f8e8dda07d1365a575ab83d9828d1)(), 0.0, 0.0, [cv::INTER_NEAREST](https://docs.opencv.org/4.x/da/d54/group__imgproc__transform.html#gga5bb5a1fea74ea38e1a5445ca803ff121aa5521d8e080972c762467c45f3b70e6c));
