void DrawHistogram3D(Histo3DData &h)
{
int planSize = (int)h.histogram.step1(0);
int cols = (int)h.histogram.step1(1);
int rows = (int)planSize / cols;
int plans = (int)h.histogram.total() / planSize;
h.fen3D->removeAllWidgets();
h.nbWidget=0;
if (h.nbWidget==0)
h.fen3D->showWidget("Axis", [viz::WCoordinateSystem](https://docs.opencv.org/4.x/df/d63/classcv_1_1viz_1_1WCoordinateSystem.html)(10));
for (int k = 0; k < plans; k++)
{
for (int i = 0; i < rows; i++)
{
for (int j = 0; j < cols; j++)
{
double x = h.histogram.at<float>(k, i, j);
if (x >= h.threshold)
double r=std::max(x/h.maxH,0.1);
[viz::WCube](https://docs.opencv.org/4.x/d2/d17/classcv_1_1viz_1_1WCube.html) s([Point3d](https://docs.opencv.org/4.x/df/d6c/classcv_1_1Point3__.html)(k - r / 2, i - r / 2, j - r / 2), [Point3d](https://docs.opencv.org/4.x/df/d6c/classcv_1_1Point3__.html)(k + r / 2, i + r / 2, j + r / 2), false, [viz::Color](https://docs.opencv.org/4.x/d4/dba/classcv_1_1viz_1_1Color.html)(j / double(plans) * 255, i / double(rows) * 255, k / double(cols) * 255));
h.fen3D->showWidget(format("I3d%d", h.nbWidget++), s);
}
}
}
h.status = false;
}
