while (true) {
capture.read(frame);
if (frame.empty()) {
break;
}
// update the background model
backSub.apply(frame, fgMask);
// get the frame number and write it on the current frame
Imgproc.rectangle(frame, new [Point](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1e83eafb2d26b3c93f09e8338bcab192)(10, 2), new [Point](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1e83eafb2d26b3c93f09e8338bcab192)(100, 20), new [Scalar](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga599fe92e910c027be274233eccad7beb)(255, 255, 255), -1);
