planes[0].[at](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa10d804e90b51d4157b5c26e12c5d2df)<float>(0) = 0;
planes[1].[at](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa10d804e90b51d4157b5c26e12c5d2df)<float>(0) = 0;
