[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) src = imread( samples::findFile( parser.get<[String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2)>( "@input" ) ) );
