{
cout << "Could not open or find the image!\n" << endl;
cout << "Usage: " << argv[0] << " <Input image>" << endl;
return -1;
}
// Show the source image
imshow("Source Image", src);
// Change the background from white to black, since that will help later to extract
// better results during the use of Distance Transform
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) mask;
inRange(src, [Scalar](https://docs.opencv.org/4.x/d1/da0/classcv_1_1Scalar__.html)(255, 255, 255), [Scalar](https://docs.opencv.org/4.x/d1/da0/classcv_1_1Scalar__.html)(255, 255, 255), mask);
src.[setTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a030678ffd9ca6e12127b3fd1337bf6e2)([Scalar](https://docs.opencv.org/4.x/d1/da0/classcv_1_1Scalar__.html)(0, 0, 0), mask);
// Show output image
imshow("Black Background Image", src);
// Create a kernel that we will use to sharpen our image
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) kernel = ([Mat_<float>](https://docs.opencv.org/4.x/df/dfc/classcv_1_1Mat__.html)(3,3) <<
1, 1, 1,
1, -8, 1,
1, 1, 1); // an approximation of second derivative, a quite strong kernel
// do the laplacian filtering as it is
// well, we need to convert everything in something more deeper then CV_8U
// because the kernel has some negative values,
// and we can expect in general to have a Laplacian image with negative values
// BUT a 8bits unsigned int (the one we are working with) can contain values from 0 to 255
// so the possible negative number will be truncated
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) imgLaplacian;
filter2D(src, imgLaplacian, [CV_32F](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga4a3def5d72b74bed31f5f8ab7676099c), kernel);
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) sharp;
src.[convertTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#adf88c60c5b4980e05bb556080916978b)(sharp, [CV_32F](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga4a3def5d72b74bed31f5f8ab7676099c));
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) imgResult = sharp - imgLaplacian;
// convert back to 8bits gray scale
imgResult.[convertTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#adf88c60c5b4980e05bb556080916978b)(imgResult, [CV_8UC3](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga88c4cd9de76f678f33928ef1e3f96047));
imgLaplacian.convertTo(imgLaplacian, [CV_8UC3](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga88c4cd9de76f678f33928ef1e3f96047));
// imshow( "Laplace Filtered Image", imgLaplacian );
imshow( "New Sharped Image", imgResult );
// Create binary image from source image
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) bw;
cvtColor(imgResult, bw, COLOR_BGR2GRAY);
threshold(bw, bw, 40, 255, THRESH_BINARY | THRESH_OTSU);
imshow("Binary Image", bw);
// Perform the distance transform algorithm
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) dist;
distanceTransform(bw, dist, DIST_L2, 3);
// Normalize the distance image for range = {0.0, 1.0}
// so we can visualize and threshold it
normalize(dist, dist, 0, 1.0, NORM_MINMAX);
imshow("Distance Transform Image", dist);
// Threshold to obtain the peaks
// This will be the markers for the foreground objects
threshold(dist, dist, 0.4, 1.0, THRESH_BINARY);
// Dilate a bit the dist image
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) kernel1 = Mat::ones(3, 3, [CV_8U](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga32b18d904ee2b1731a9416a8eef67d06));
dilate(dist, dist, kernel1);
imshow("Peaks", dist);
// Create the CV_8U version of the distance image
// It is needed for findContours()
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) dist_8u;
dist.[convertTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#adf88c60c5b4980e05bb556080916978b)(dist_8u, [CV_8U](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga32b18d904ee2b1731a9416a8eef67d06));
// Find total markers
vector<vector<Point> > contours;
