void loadExposureSeq([String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2) path, vector<Mat>& images, vector<float>& times)
{
path = path + "/";
ifstream list_file((path + "list.txt").c_str());
string name;
float val;
while(list_file >> name >> val) {
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) img = imread(path + name);
images.push_back(img);
times.push_back(1 / val);
}
list_file.close();
}
