/*std::string*/ faceDevice
};
auto landmParams = [cv::gapi::ie::Params<custom::LandmDetector>](https://docs.opencv.org/4.x/d7/dda/classcv_1_1gapi_1_1ie_1_1Params.html)
{
/*std::string*/ landmXmlPath,
/*std::string*/ landmBinPath,
/*std::string*/ landmDevice
