private void update() {
dst = Mat.zeros(srcGray.size(), CvType.CV_32F);
int blockSize = 2;
int apertureSize = 3;
double k = 0.04;
Imgproc.cornerHarris(srcGray, dst, blockSize, apertureSize, k);
