[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) viewGray;
[cvtColor](https://docs.opencv.org/4.x/d8/d01/group__imgproc__color__conversions.html#gaf86c09fe702ed037c03c2bc603ceab14)(view, viewGray, COLOR_BGR2GRAY);
