static void read_write_attributes()
{
[String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2) filename = "attributes.h5";
[Ptr<hdf::HDF5>](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga524e5e94ebf48db273a71ab275eaf5b5) h5io = hdf::open(filename);
