[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) attr_mat;
attr_mat = ([cv::Mat_<float>](https://docs.opencv.org/4.x/df/dfc/classcv_1_1Mat__.html)(2, 3) << 0, 1, 2, 3, 4, 5, 6);
if (!h5io->atexists(attr_mat_name))
h5io->atwrite(attr_mat, attr_mat_name);
[String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2) attr_str_name = "string attribute";
[String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2) attr_str = "Hello HDF5 from OpenCV!";
if (!h5io->atexists(attr_str_name))
h5io->atwrite(attr_str, attr_str_name);
[String](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga1f6634802eeadfd7245bc75cf3e216c2) attr_int_name = "int attribute";
int attr_int = 123456;
