[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) draw;
sobelx.[convertTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#adf88c60c5b4980e05bb556080916978b)(draw, [CV_8U](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga32b18d904ee2b1731a9416a8eef67d06), 255.0/(maxVal - minVal), -minVal * 255.0/(maxVal - minVal));
