s1.[convertTo](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#adf88c60c5b4980e05bb556080916978b)(s1, [CV_32F](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga4a3def5d72b74bed31f5f8ab7676099c)); // cannot make a square on 8 bits
